// Normalise order from Shopify/Eventbrite, classify ticket tier, build a QR token
const body = $input.first().json.body || $input.first().json;
const email = (body.email || body.customer?.email || '').trim().toLowerCase();
const name = body.name || [body.customer?.first_name, body.customer?.last_name].filter(Boolean).join(' ') || 'Guest';
const lineItem = (body.line_items && body.line_items[0]) || {};
const title = (lineItem.title || body.ticket_type || 'General Admission').toLowerCase();
let tier = 'GA';
if (title.includes('vip')) tier = 'VIP';
else if (title.includes('reseller') || title.includes('vendor')) tier = 'Reseller';
else if (title.includes('early')) tier = 'Early Bird';
const orderId = body.order_id || body.id || ('SF-' + Date.now());
const qrToken = Buffer.from(`${orderId}:${email}`).toString('base64url');
return [{ json: {
  email, name, tier, orderId, qrToken,
  quantity: lineItem.quantity || 1,
  qrUrl: `https://api.qrserver.com/v1/create-qr-code/?size=600x600&data=https://sneakerfest.com/checkin/${qrToken}`,
  purchasedAt: new Date().toISOString()
} }];
